1	import { KEYS, arrayToMap, randomId } from "@excalidraw/common";
2	
3	import {
4	  elementsAreInSameGroup,
5	  getNonDeletedElements,
6	  newElementWith,
7	  selectGroupsFromGivenElements,
8	} from "@excalidraw/element";
9	
10	import { CaptureUpdateAction } from "@excalidraw/element";
11	
12	import type { ExcalidrawElement } from "@excalidraw/element/types";
13	
14	import { LockedIcon, UnlockedIcon } from "../components/icons";
15	
16	import { getSelectedElements } from "../scene";
17	
18	import { register } from "./register";
19	
20	import type { AppState } from "../types";
21	
22	const shouldLock = (elements: readonly ExcalidrawElement[]) =>
23	  elements.every((el) => !el.locked);
24	
25	export const actionToggleElementLock = register({
26	  name: "toggleElementLock",
27	  label: (elements, appState, app) => {
28	    const selected = app.scene.getSelectedElements({
29	      selectedElementIds: appState.selectedElementIds,
30	      includeBoundTextElement: false,
31	    });
32	
33	    return shouldLock(selected)
34	      ? "labels.elementLock.lock"
35	      : "labels.elementLock.unlock";
36	  },
37	  icon: (appState, elements) => {
38	    const selectedElements = getSelectedElements(elements, appState);
39	    return shouldLock(selectedElements) ? LockedIcon : UnlockedIcon;
40	  },
41	  trackEvent: { category: "element" },
42	  predicate: (elements, appState, _, app) => {
43	    const selectedElements = app.scene.getSelectedElements(appState);
44	    return (
45	      selectedElements.length > 0 &&
46	      !selectedElements.some((element) => element.locked && element.frameId)
47	    );
48	  },
49	  perform: (elements, appState, _, app) => {
50	    const selectedElements = app.scene.getSelectedElements({
51	      selectedElementIds: appState.selectedElementIds,
52	      includeBoundTextElement: true,
53	      includeElementsInFrames: true,
54	    });
55	
56	    if (!selectedElements.length) {
57	      return false;
58	    }
59	
60	    const nextLockState = shouldLock(selectedElements);
61	    const selectedElementsMap = arrayToMap(selectedElements);
62	
63	    const isAGroup =
64	      selectedElements.length > 1 && elementsAreInSameGroup(selectedElements);
65	    const isASingleUnit = selectedElements.length === 1 || isAGroup;
66	    const newGroupId = isASingleUnit ? null : randomId();
67	
68	    let nextLockedMultiSelections = { ...appState.lockedMultiSelections };
69	
70	    if (nextLockState) {
71	      nextLockedMultiSelections = {
72	        ...appState.lockedMultiSelections,
73	        ...(newGroupId ? { [newGroupId]: true } : {}),
74	      };
75	    } else if (isAGroup) {
76	      const groupId = selectedElements[0].groupIds.at(-1)!;
77	      delete nextLockedMultiSelections[groupId];
78	    }
79	
80	    const nextElements = elements.map((element) => {
81	      if (!selectedElementsMap.has(element.id)) {
82	        return element;
83	      }
84	
85	      let nextGroupIds = element.groupIds;
86	
87	      // if locking together, add to group
88	      // if unlocking, remove the temporary group
89	      if (nextLockState) {
90	        if (newGroupId) {
91	          nextGroupIds = [...nextGroupIds, newGroupId];
92	        }
93	      } else {
94	        nextGroupIds = nextGroupIds.filter(
95	          (groupId) => !appState.lockedMultiSelections[groupId],
96	        );
97	      }
98	
99	      return newElementWith(element, {
100	        locked: nextLockState,
101	        // do not recreate the array unncessarily
102	        groupIds:
103	          nextGroupIds.length !== element.groupIds.length
104	            ? nextGroupIds
105	            : element.groupIds,
106	      });
107	    });
108	
109	    const nextElementsMap = arrayToMap(nextElements);
110	    const nextSelectedElementIds: AppState["selectedElementIds"] = nextLockState
111	      ? {}
112	      : Object.fromEntries(selectedElements.map((el) => [el.id, true]));
113	    const unlockedSelectedElements = selectedElements.map(
114	      (el) => nextElementsMap.get(el.id) || el,
115	    );
116	    const nextSelectedGroupIds = nextLockState
117	      ? {}
118	      : selectGroupsFromGivenElements(
119	          getNonDeletedElements(unlockedSelectedElements),
120	          appState,
121	        );
122	
123	    const activeLockedId = nextLockState
124	      ? newGroupId
125	        ? newGroupId
126	        : isAGroup
127	        ? selectedElements[0].groupIds.at(-1)!
128	        : selectedElements[0].id
129	      : null;
130	
131	    return {
132	      elements: nextElements,
133	
134	      appState: {
135	        ...appState,
136	        selectedElementIds: nextSelectedElementIds,
137	        selectedGroupIds: nextSelectedGroupIds,
138	        selectedLinearElement: nextLockState
139	          ? null
140	          : appState.selectedLinearElement,
141	        lockedMultiSelections: nextLockedMultiSelections,
142	        activeLockedId,
143	      },
144	      captureUpdate: CaptureUpdateAction.IMMEDIATELY,
145	    };
146	  },
147	  keyTest: (event, appState, elements, app) => {
148	    return (
149	      event.key.toLocaleLowerCase() === KEYS.L &&
150	      event[KEYS.CTRL_OR_CMD] &&
151	      event.shiftKey &&
152	      app.scene.getSelectedElements({
153	        selectedElementIds: appState.selectedElementIds,
154	        includeBoundTextElement: false,
155	      }).length > 0
156	    );
